import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { primitives } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector2 } = ctx.THREE;

  // Root container
  const root = new Group();

  // Store resources for cleanup
  const resources = {
    texture: null,
    material: null,
    geometry: null,
    timelines: [],
    primitives: [],
  };
  root.userData._resources = resources;

  // ---------- TEXTURED PLANE ----------
  const imageUrl = config.imageUrl ?? config.meshUrl ?? null;
  if (imageUrl) {
    // Plane size based on atlas region (512x320) aspect ratio
    const atlasWidth = 512;
    const atlasHeight = 320;
    const aspect = atlasWidth / atlasHeight;
    const planeWidth = 2; // arbitrary scene units
    const planeHeight = planeWidth / aspect;

    const geometry = new PlaneGeometry(planeWidth, planeHeight);
    const material = new MeshBasicNodeMaterial();
    // default color is white; texture will define appearance
    const mesh = new Mesh(geometry, material);
    // Ensure plane faces camera (billboard) – will be updated by outer render loop if needed
    mesh.rotation.set(0, 0, 0);
    root.add(mesh);

    // Store for cleanup
    resources.geometry = geometry;
    resources.material = material;

    // Load texture asynchronously
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      resources.texture = tex;
    });
  }

  // ---------- TEXT CONTENT ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const textStr = item.text ?? '';
    const fontSize = item.typography?.fontSize ?? 96;
    const color = config.intent?.visualSpec?.colors?.ink ?? '#16161d';
    const textObj = ctx.fontAtlas.createText(textStr, {
      fontSize,
      color,
      align: 'center',
    });
    // Position text slightly in front of the plane to avoid Z‑fight
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
  }

  // ---------- PRIMITIVES ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const { name, params, trigger } = prim;
      if (typeof ctx.primitives[name] === 'function') {
        const primInst = ctx.primitives[name](root, params);
        resources.primitives.push(primInst);
        // If primitive provides a timeline, keep reference for cleanup
        if (primInst.timeline) {
          resources.timelines.push(primInst.timeline);
        }
      }
    }
  }

  // ---------- HANDLERS ----------
  root.userData.handlers = {};

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    // Dispose texture
    if (resources.texture) {
      resources.texture.dispose();
    }
    // Dispose material
    if (resources.material) {
      resources.material.dispose();
    }
    // Dispose geometry
    if (resources.geometry) {
      resources.geometry.dispose();
    }
    // Kill GSAP timelines
    for (const tl of resources.timelines) {
      tl.kill();
    }
    // Cleanup primitives
    for (const p of resources.primitives) {
      if (p.cleanup) p.cleanup();
    }
    // Remove from parent if attached
    if (root.parent) {
      root.parent.remove(root);
    }
  };

  return root;
}
